-- Fixes the v3.45 KML MultiGeometry import bug for one already-imported
-- segment: GERK 2615672 (order #99/#98/#27, "Luka Boltiš - HR"), segment
-- "12749" imported as a 0.00013 ha sliver (only the first <Polygon> of its
-- <MultiGeometry>) instead of its real ~1.39 ha shape (both polygons).
--
-- Coordinates extracted programmatically from
-- 2615672_Boltis_L_soil_sampling_12749-12751zones_09_30_2026.kml (not
-- hand-typed) — same MultiPolygon the fixed client-side parser would now
-- produce on a fresh import. Targets this one segment row directly rather
-- than re-running the full import, since segments 12750/12751 in the same
-- segmentation batch already imported correctly and don't need to change.

update gerk_segment
   set polygon_points = ST_Multi(ST_SetSRID(ST_GeomFromGeoJSON(
     '{"type":"MultiPolygon","coordinates":[[[[16.3006743766638,45.6433764767792],[16.3006738964974,45.6433557302296],[16.3006599941658,45.6433700576738],[16.3006730301866,45.6433764921108],[16.3006743766638,45.6433764767792]]],[[[16.300800111878,45.6432850744623],[16.3009279288468,45.6432836187969],[16.30093001102,45.6433735655825],[16.3010578281835,45.6433721097696],[16.3011856453371,45.6433706538138],[16.301313462481,45.6433691977151],[16.301441279615,45.6433677414733],[16.3015690967393,45.6433662850886],[16.3016969138537,45.643364828561],[16.3016948304539,45.6432748818027],[16.3018226473541,45.6432734251366],[16.3019504642445,45.6432719683276],[16.3019483804456,45.6431820215769],[16.3019462966566,45.6430920748247],[16.3018184801751,45.6430935316247],[16.3018163966004,45.6430035848664],[16.3018143130356,45.6429136381067],[16.3016864969531,45.6429150947546],[16.3016844136026,45.6428251479889],[16.3016823302619,45.6427352012216],[16.3017145592276,45.6427348339274],[16.3008667217003,45.6423969018432],[16.2999498397925,45.642035362538],[16.299936015496,45.6422683830044],[16.2997692466921,45.6428343392362],[16.299849870653,45.6428637696888],[16.299963830039,45.6429127845742],[16.3007754873688,45.6432510328602],[16.3007418116239,45.6432857383594],[16.300800111878,45.6432850744623]]]]}'
   ), 4326))
 where segmentation_id = '0e172156-0fd2-41ed-8c5c-c68ba68726c2'
   and label = '12749';

-- Verify: should now show num_parts=2 and area_ha close to 1.39 (the KML's
-- own declared area for this segment), matching 12750/12751's pattern.
select label, ST_NumGeometries(polygon_points) as num_parts, ST_Area(polygon_points::geography)/10000 as area_ha
  from gerk_segment
 where segmentation_id = '0e172156-0fd2-41ed-8c5c-c68ba68726c2'
 order by label;
